<script setup>
import { ref,onMounted,onBeforeUnmount } from 'vue'; import EraLmsLayout from '@/Layouts/EraLmsLayout.vue'
const current=ref(1); const answered=ref([1,2]); const review=ref([3]); let timer=null; const seconds=ref(2700)
function event(name){console.log('exam event',name)} onMounted(()=>{timer=setInterval(()=>seconds.value--,1000);document.addEventListener('visibilitychange',()=>event(document.hidden?'tab_hidden':'tab_visible'));document.addEventListener('copy',()=>event('copy_attempt'));document.addEventListener('paste',()=>event('paste_attempt'))}); onBeforeUnmount(()=>clearInterval(timer))
</script>
<template><EraLmsLayout><template #breadcrumb>Làm bài kiểm tra</template><section class="mx-auto grid max-w-7xl gap-4 px-6 py-5 lg:grid-cols-[260px_1fr_280px]"><aside class="border bg-white p-4"><h2 class="text-sm font-semibold">Danh sách câu hỏi</h2><div class="mt-3 grid grid-cols-5 gap-2"><button v-for="i in 30" :key="i" class="h-9 rounded border text-sm" :class="answered.includes(i)?'bg-emerald-50 text-emerald-700':review.includes(i)?'bg-amber-50 text-amber-800':'bg-white'" @click="current=i">{{i}}</button></div></aside><main class="border bg-white p-5"><div class="flex justify-between"><h1 class="text-lg font-semibold">Câu {{current}}</h1><button class="rounded-md border px-3 py-2 text-sm">Đánh dấu xem lại</button></div><p class="mt-4 text-sm leading-6">Nội dung câu hỏi được lấy từ snapshot của attempt. Hệ thống không gửi đáp án đúng xuống client khi đang làm bài.</p><div class="mt-4 space-y-2"><label v-for="o in ['A','B','C','D']" :key="o" class="block rounded-md border p-3 text-sm"><input type="radio" name="answer" class="mr-2"/> Đáp án {{o}}</label></div><div class="mt-5 flex gap-2"><button class="rounded-md border px-3 py-2 text-sm">Lưu tự động</button><button class="rounded-md bg-slate-950 px-3 py-2 text-sm text-white">Câu tiếp theo</button></div></main><aside class="space-y-4"><div class="border bg-white p-4"><h2 class="text-sm font-semibold">Thời gian còn lại</h2><div class="mt-2 text-2xl font-semibold">{{Math.floor(seconds/60)}}:{{String(seconds%60).padStart(2,'0')}}</div></div><div class="border bg-white p-4 text-sm text-slate-700">Fullscreen-friendly, ghi nhận tab switch, copy/paste, fullscreen exit và reconnect.</div><button class="w-full rounded-md bg-rose-700 px-3 py-2 text-sm text-white">Nộp bài</button></aside></section></EraLmsLayout></template>
